package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
public final class FilmSearchActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private LinearLayout list;private EditText query;private TextView status;private Spinner choice;private List<TvBoxConfig.Site> sources=new ArrayList<>();private volatile int generation;private Future<?> searchJob;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=TvUi.root(this);root.addView(TvUi.title(this,"搜寻你的下一部",26));query=new EditText(this);query.setSingleLine(true);query.setTextColor(TvUi.INK);query.setHintTextColor(TvUi.MUTED);query.setHint("搜索电影、剧集或戏曲");TvUi.styleSearch(this,query);root.addView(query);if(state!=null)query.setText(state.getString("query",""));try{sources=new SourceRepository(this).load().sites;}catch(Exception ignored){}List<String> names=new ArrayList<>();names.add("全部支持的标准 API");for(TvBoxConfig.Site site:sources)names.add(site.name);choice=new Spinner(this);choice.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));choice.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int n,long id){if(v instanceof TextView)((TextView)v).setTextColor(TvUi.INK);}});root.addView(choice);LinearLayout buttons=TvUi.row(this);Button search=TvUi.button(this,"搜索"),back=TvUi.button(this,"返回");buttons.addView(search,new LinearLayout.LayoutParams(0,-2,1));buttons.addView(back);root.addView(buttons);search.setOnClickListener(v->search());back.setOnClickListener(v->finish());status=TvUi.text(this,sources.isEmpty()?"请先在设置中导入 TVBox 配置。":"已加载 "+sources.size()+" 个标准 API，结果由所选源返回。",16,TvUi.MUTED);root.addView(status);ScrollView scroll=new ScrollView(this);list=TvUi.col(this);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 private static final class Result{TvBoxConfig.Site site;List<VodApi.Movie> movies;Result(TvBoxConfig.Site s,List<VodApi.Movie> m){site=s;movies=m;}}
 private void search(){
  String word=query.getText().toString().trim();if(word.isEmpty()||sources.isEmpty()){TvUi.toast(this,sources.isEmpty()?"尚无影视源，请先导入配置":"请输入片名");return;}
  int token=++generation;if(searchJob!=null)searchJob.cancel(true);int selected=choice.getSelectedItemPosition();List<TvBoxConfig.Site> targets=selected<=0?new ArrayList<>(sources):Collections.singletonList(sources.get(selected-1));status.setText("正在搜索 · 有结果即显示");list.removeAllViews();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);
  searchJob=worker.submit(()->{if(token!=generation)return;ExecutorService requests=Executors.newFixedThreadPool(3);CompletionService<Result> completed=new ExecutorCompletionService<>(requests);for(TvBoxConfig.Site site:targets)completed.submit(()->new Result(site,VodApi.parse(PublicHttp.get(VodApi.query(site.api,"wd",word)))));int failures=0,finished=0;long deadline=android.os.SystemClock.elapsedRealtime()+18000;final int[] visible={0};
   try{while(finished<targets.size()&&token==generation){long remaining=deadline-android.os.SystemClock.elapsedRealtime();if(remaining<=0)break;Future<Result> next=completed.poll(remaining,TimeUnit.MILLISECONDS);if(next==null)break;finished++;try{Result result=next.get();for(VodApi.Movie movie:result.movies)VodCache.put(result.site.api,movie);int progress=finished;runOnUiThread(()->{if(isDestroyed()||token!=generation)return;for(VodApi.Movie movie:result.movies){if(visible[0]>=120)break;visible[0]++;Button card=TvUi.button(this,movie.title+"\n"+movie.category+" · "+movie.year+" · "+result.site.name);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.bottomMargin=TvUi.dp(this,10);list.addView(card,params);card.setOnClickListener(v->startActivity(new Intent(this,EpisodeActivity.class).putExtra("api",result.site.api).putExtra("source",result.site.name).putExtra("site",result.site.key).putExtra("movie",movie.id).putExtra("title",movie.title)));}status.setText(visible[0]+" 项结果 · 已完成 "+progress+"/"+targets.size()+" 个源");});}catch(ExecutionException|CancellationException e){failures++;}}
   }catch(InterruptedException e){Thread.currentThread().interrupt();}finally{requests.shutdownNow();}int failed=failures+targets.size()-finished;runOnUiThread(()->{if(!isDestroyed()&&token==generation)status.setText(visible[0]+" 项结果 · "+failed+" 个源未响应");});
  });
 }
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("query",query.getText().toString());}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
}
